528	function buildSessions() {
529	  const grid = document.getElementById('sessionGrid');
530	  const select = document.getElementById('regSession');
531	  let n = 0;
532	  SESSION_DATES.forEach(d => {
533	    d.slots.forEach(s => {
534	      n++;
535	      const t = SLOTS[s];
536	      const isTBD = s === 'TBD';
537	      const sessionLabel = isTBD ? `${d.label} 時間確認後公告` : `${d.label} ${s}場 ${t.start}–${t.end}`;
538	      const card = document.createElement('div');
539	      card.className = 'session-card bg-white rounded-2xl p-6';
540	      card.innerHTML = `
541	        <div class="text-sm font-bold text-accent2 tracking-widest mb-1">第 ${n} 場</div>
542	        <div class="serif font-black text-3xl text-deep mb-1 flex items-center flex-wrap gap-2">
