548	        <div class="font-bold text-accent2 text-base mb-5">主題：${d.topic}</div>
549	        ${d.closed ? `<button disabled class="w-full py-3 rounded-full font-bold bg-gray-300 text-gray-500 cursor-not-allowed">已截止報名</button>` : `<button onclick="showRegisterModal('${sessionLabel}')" class="btn-primary w-full py-3 rounded-full font-bold">我要報名這場</button>`}
550	      `;
551	      grid.appendChild(card);
552	
553	      const opt = document.createElement('option');
554	      opt.value = sessionLabel;
555	      opt.textContent = sessionLabel;
556	      select.appendChild(opt);
557	    });
558	  });
559	}
